const app=document.querySelector('#app');
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let sound=true,level=1,stars=0,round=null,position=0,answered=false;
try{stars=Number(localStorage.getItem('playSay.stars'))||0;level=Number(localStorage.getItem('playSay.level'))||1;if(![1,2,3].includes(level))level=1}catch{}
const activities=[['numbers','Number garden','Count, add & grow.','🍎','peach'],['words','Word safari','Letters, sounds & smiles.','🦁','lavender'],['puzzles','Puzzle playground','A little think. A big aha!','🧩','blue'],['stories','Story meadow','A new adventure awaits.','📖','pink']];
function speak(text){if(!sound)return;if(!('speechSynthesis'in window)){document.querySelector('#sound').textContent='Voice unavailable';return}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.rate=.85;speechSynthesis.speak(u)}
document.querySelector('#sound').onclick=()=>{sound=!sound;if(!sound&&'speechSynthesis'in window)speechSynthesis.cancel();document.querySelector('#sound').textContent=sound?'🔊 Sound on':'🔇 Sound off';document.querySelector('#sound').setAttribute('aria-label',sound?'Turn voice instructions off':'Turn voice instructions on')};
function home(){round=null;if('speechSynthesis'in window)speechSynthesis.cancel();app.innerHTML=`<section class="hero"><div><span class="eyebrow">A LITTLE PLAY. A LOT OF WONDER.</span><h1>Big adventures for<br>little thinkers.</h1><p>Count a little. Wonder a little. Find something new with your brain buddy today.</p><button class="primary" id="start">Let’s play! &nbsp; →</button></div><div class="hero-art" aria-label="A smiling green buddy with a book"><div class="orbit"></div><span class="sun">☀️</span><span class="art-star">✨</span><div class="buddy"><span class="cheek"></span></div><span class="art-book">📚</span><span class="buddy-tag">Hi, friend! Ready to explore? 🌱</span></div></section><section aria-labelledby="choose"><div class="section-top"><div><h2 id="choose">What shall we play?</h2><p>Pick a little adventure. Follow your curiosity.</p></div><label><span class="eyebrow">PLAY LEVEL </span><br><select id="level" aria-label="Learning level"><option value="1">Little learner · 5–7</option><option value="2">Explorer · 8–11</option><option value="3">Champion · 12–15</option></select></label></div><div class="activities">${activities.map(([id,title,desc,art,color])=>`<button class="activity ${color}" data-activity="${id}"><span class="art" aria-hidden="true">${art}</span><h3>${title}</h3><p>${desc}</p><span class="go">LET’S EXPLORE <span class="arrow">↗</span></span></button>`).join('')}</div></section><div class="bottom-grid"><section class="voice-card"><span class="voice-icon" aria-hidden="true">🎙️</span><div><h3>Small voice. Big ideas.</h3><p>Tell a story or save a “guess what!” moment.</p><button class="text-button" id="openVoice">Make a voice note &nbsp; →</button></div></section><section class="progress-card"><span class="star-circle" aria-hidden="true">🌟</span><div><h3>Look at you grow!</h3><p>${stars} discovery ${stars===1?'star':'stars'} collected on this device.</p><div class="stars" aria-hidden="true">${'★'.repeat(Math.min(5,stars))}${'☆'.repeat(Math.max(0,5-stars))}</div></div></section></div>`;document.querySelector('#level').value=level;document.querySelector('#level').onchange=e=>{level=Number(e.target.value);try{localStorage.setItem('playSay.level',level)}catch{}};document.querySelectorAll('[data-activity]').forEach(b=>b.onclick=()=>start(b.dataset.activity));document.querySelector('#start').onclick=()=>start('numbers');document.querySelector('#openVoice').onclick=openVoice}
document.querySelector('.brand').onclick=e=>{e.preventDefault();home()};
function start(activity){round=buildRound(activity,level).slice(0,5);position=0;showQuestion()}
function readQuestion(q){speak((q.story?q.story.text+'. ':'')+(q.speak||stripTags(q.prompt)))}
function showQuestion(){answered=false;const q=round[position];app.innerHTML=`<div class="game-shell"><div class="game-nav"><button id="back">← All adventures</button><span>Little step ${position+1} of ${round.length}</span><button id="read">🔊 Read to me</button></div><div class="round-progress"><span style="width:${position/round.length*100}%"></span></div><section class="question-card">${q.story?`<div class="eyebrow">${escapeHTML(q.story.title)}</div><div class="visual">${q.story.art}</div><p class="story">${escapeHTML(q.story.text)}</p>`:''}<h2>${q.prompt}</h2><div class="visual">${q.visual||''}</div><div class="choices">${q.choices.map((c,i)=>`<button data-answer="${i}">${c}</button>`).join('')}</div><div class="feedback" role="status">Take your time. You’ve got this.</div><button id="next" class="primary" hidden>Next little step →</button><button class="text-button" id="activityVoice">🎙️ Say it in a voice note</button></section></div>`;document.querySelector('#back').onclick=home;document.querySelector('#read').onclick=()=>readQuestion(q);document.querySelector('#activityVoice').onclick=openVoice;document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{if(answered)return;const correct=Number(b.dataset.answer)===q.answer;const feedback=document.querySelector('.feedback');b.classList.add(correct?'correct':'retry');if(!correct){feedback.textContent='Good try! Take another look. 🌱';speak('Good try! Take another look.');return}answered=true;stars++;try{localStorage.setItem('playSay.stars',stars)}catch{}feedback.textContent='You did it! A discovery star for you. ⭐';speak('You did it!');document.querySelectorAll('[data-answer]').forEach(x=>x.disabled=true);document.querySelector('#next').hidden=false;document.querySelector('#next').focus()});document.querySelector('#next').onclick=()=>{position++;if(position<round.length)showQuestion();else finish()};if(q.autoSpeak)readQuestion(q)}
function finish(){app.innerHTML=`<section class="question-card game-shell"><div class="visual">🌟 🌈 🌟</div><span class="eyebrow">ADVENTURE COMPLETE</span><h1>You did a wonderful thing.</h1><p>You explored, practised, and kept going.<br>You’ve collected ${stars} discovery stars!</p><button class="primary" id="again">Choose another adventure →</button><p><button class="text-button" id="celebrate">🎙️ Tell me your favourite part</button></p></section>`;document.querySelector('#again').onclick=home;document.querySelector('#celebrate').onclick=openVoice}
// IndexedDB keeps audio blobs on this device, without uploading recordings.
let dbPromise;
function database(){if(!dbPromise)dbPromise=new Promise((resolve,reject)=>{const request=indexedDB.open('playSay.voiceNotes',1);request.onupgradeneeded=()=>request.result.createObjectStore('notes',{keyPath:'id'});request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)});return dbPromise}
async function noteStore(mode,action){const db=await database();return new Promise((resolve,reject)=>{const tx=db.transaction('notes',mode),req=action(tx.objectStore('notes'));let value;req.onsuccess=()=>value=req.result;tx.oncomplete=()=>resolve(value);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)})}
const voice=document.querySelector('#voice'),status=document.querySelector('#recordStatus'),recordButton=document.querySelector('#record');let recorder=null,stream=null,timer=null,ticker=null,recordStart=0,pending=false,urls=[];
async function openVoice(){voice.showModal();status.textContent='Your voice belongs here.';await renderNotes()}
async function renderNotes(){urls.forEach(URL.revokeObjectURL);urls=[];const target=document.querySelector('#notes');try{const notes=await noteStore('readonly',s=>s.getAll());notes.sort((a,b)=>b.id-a.id);target.innerHTML=notes.length?notes.map((n,i)=>{const url=URL.createObjectURL(n.blob);urls.push(url);return `<article class="note"><strong>My voice note ${notes.length-i}</strong><div class="small">${escapeHTML(new Date(n.id).toLocaleString())}</div><audio controls src="${url}" aria-label="Voice note ${notes.length-i}"></audio><div class="note-actions"><a href="${url}" download="my-voice-note-${n.id}.${n.blob.type.includes('mp4')?'m4a':'webm'}">↓ Download</a><button class="text-button" data-delete="${n.id}">Delete note</button></div></article>`}).join(''):'<p class="empty">Your little collection starts with one hello.</p>';target.querySelectorAll('[data-delete]').forEach(b=>b.onclick=async()=>{try{await noteStore('readwrite',s=>s.delete(Number(b.dataset.delete)));await renderNotes()}catch{status.textContent='Could not delete this note. Please try again.'}})}catch{target.innerHTML='<p class="empty">Voice-note storage is unavailable. Enable browser storage to keep recordings.</p>'}}
function stopRecording(){clearTimeout(timer);clearInterval(ticker);if(recorder&&recorder.state==='recording')recorder.stop();if(stream){stream.getTracks().forEach(t=>t.stop());stream=null}}
recordButton.onclick=async()=>{if(recorder&&recorder.state==='recording'){stopRecording();return}if(pending)return;if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){status.textContent='Recording needs a supported browser on HTTPS or localhost.';return}pending=true;recordButton.disabled=true;status.textContent='Allow the microphone when your browser asks.';try{await database();stream=await navigator.mediaDevices.getUserMedia({audio:true});if(!voice.open){stream.getTracks().forEach(t=>t.stop());stream=null;return}if('speechSynthesis'in window)speechSynthesis.cancel();document.querySelectorAll('audio').forEach(a=>a.pause());const chunks=[];recorder=new MediaRecorder(stream);recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};recorder.onerror=()=>{status.textContent='Recording stopped. Please try again.';stopRecording()};recorder.onstop=async()=>{clearTimeout(timer);clearInterval(ticker);recordButton.disabled=true;recordButton.classList.remove('recording');recordButton.textContent='● Start recording';try{if(chunks.length){await noteStore('readwrite',s=>s.put({id:Date.now(),blob:new Blob(chunks,{type:recorder.mimeType})}));status.textContent='Saved! Press play to hear your voice. 💚';await renderNotes()}else status.textContent='No audio captured. Please try again.'}catch{status.textContent='This note could not be saved. Browser storage may be full.'}finally{recordButton.disabled=false}};recorder.start();recordStart=Date.now();recordButton.textContent='■ Stop & save';recordButton.classList.add('recording');status.textContent='Recording… 0:00 / 1:00';ticker=setInterval(()=>{const s=Math.min(60,Math.floor((Date.now()-recordStart)/1000));status.textContent=`Recording… ${Math.floor(s/60)}:${String(s%60).padStart(2,'0')} / 1:00`},250);timer=setTimeout(stopRecording,60000)}catch(e){if(stream){stream.getTracks().forEach(t=>t.stop());stream=null}status.textContent=e.name==='NotAllowedError'?'Microphone access is off. Ask a grown-up to help enable it, then try again.':'Could not open the microphone or storage. Check your browser settings and try again.'}finally{pending=false;recordButton.disabled=false}};
document.querySelector('#closeVoice').onclick=()=>voice.close();voice.addEventListener('close',()=>{stopRecording();document.querySelectorAll('audio').forEach(a=>a.pause())});window.addEventListener('pagehide',stopRecording);home();
